@PluginDescriptor(
	name = "Max Hit",
	description = "Displays current max hit",
	enabledByDefault = true,
	tags = {"max, hit, spec, pvp, magic, spell, combat, gear"}
)

@Slf4j
public class MaxHitPlugin extends Plugin
{

	private static final int WEAPON_SPECIAL_REQS = 906;
	private static final Duration WAIT = Duration.ofSeconds(5);


	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ItemManager itemManager;
	@Inject
	private MaxHitOverlay myOverlay;
	@Inject
	private MaxHitConfig config;

	@Provides
	MaxHitConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MaxHitConfig.class);
	}

	private Instant lastTime;
	private ItemContainer equippedItems;
	private MaxHitCalculatorFactory maxHitCalculatorFactory;
	@Getter
	private MaxHitCalculator maxHitCalculator;
	@Getter
	private SpecialAttackCalculator specialAttackCalculator;
	//Might be better to break this out into own class
	@Getter
	private boolean isWieldingSpecialAttackWeapon = false;
	@Getter
	public HashMap<String, InventoryWeapon> map;

	@Getter
	private MagicSpell activeSpell;

	@Getter
	private final List<NPC> targets = new ArrayList<>();

	@Getter
	@Setter
	private int amount;

	@Getter
	@Setter
	private int initialAmount;

	@Getter
	@Setter
	private String taskLocation;

	@Getter
	@Setter
	private String taskName;

	private boolean loginFlag;
	private final List<Pattern> targetNames = new ArrayList<>();

	@Override
	public void startUp() throws Exception
	{
		overlayManager.add(myOverlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loginFlag = true;
			clientThread.invoke(this::updateTask);
		}


		clientThread.invokeLater(() ->
		{
			maxHitCalculatorFactory = new MaxHitCalculatorFactory(this, client, itemManager);
			specialAttackCalculator = new SpecialAttackCalculator(client);

			if (!client.getGameState().equals(GameState.LOGGED_IN))
			{
				return;
			}

			equippedItems = client.getItemContainer(InventoryID.WORN);
			if (equippedItems == null)
			{
				return;
			}
			// Safe to assume combat Varbits have been set here?
			replaceCalculatorAndMaxHit();

		});
	}

	@Override
	public void shutDown() throws Exception
	{
		overlayManager.remove(myOverlay);
		targets.clear();
		lastTime = null;
		isWieldingSpecialAttackWeapon = false;
		maxHitCalculatorFactory = null;
		specialAttackCalculator = null;
		maxHitCalculator = null;
		activeSpell = null;
	}

	private void updateTask()
	{
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (amount > 0)
		{
			int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

			int taskDBRow;
			if (taskId == 98 /* Bosses, from [proc,helper_slayer_current_assignment] */)
			{
				var bossRows = client.getDBRowsByValue(
					DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
					0,
					client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));

				if (bossRows.isEmpty())
				{
					return;
				}
				taskDBRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			}
			else
			{
				var taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (taskRows.isEmpty())
				{
					return;
				}
				taskDBRow = taskRows.get(0);
			}

			var taskName = (String) client.getDBTableField(taskDBRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];

			int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
			String taskLocation = null;
			if (areaId > 0)
			{
				var areaRows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
				if (areaRows.isEmpty())
				{
					return;
				}

				taskLocation = (String) client.getDBTableField(areaRows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
			}

			int initialAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
			if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == 2)
			{
				boolean isNegative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
				int modifierValue = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
				initialAmount += isNegative ? -modifierValue : modifierValue;
			}

			if (loginFlag)
			{
				setTask(taskName, amount, initialAmount, taskLocation);
			}
			else if (!Objects.equals(taskName, this.taskName) || !Objects.equals(taskLocation, this.taskLocation))
			{
				setTask(taskName, amount, initialAmount, taskLocation);
			}
		}
		else
		{
			setNoTask();
		}
	}

	public boolean isTarget(NPC npc)
	{
		if (targetNames.isEmpty())
		{
			return false;
		}

		final NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			return false;
		}

		final String name = composition.getName()
			.replace('\u00A0', ' ')
			.toLowerCase();

		boolean matchingTarget = false;
		for (Pattern target : targetNames)
		{
			final Matcher targetMatcher = target.matcher(name);
			if (targetMatcher.find())
			{
				matchingTarget = true;
			}
		}

		if (!matchingTarget)
		{
			return false;
		}

		for (TaskLocation location : TaskLocation.values())
		{
			if (!location.getName().equals(taskLocation))
			{
				continue;
			}


			int region = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();

			if ( IntStream.of(location.getRegionIds()).anyMatch(x -> x == region))
			{
				return true;
			}
		}

		return false;
	}

	private void rebuildTargetNames(Task task)
	{
		targetNames.clear();

		if (task != null)
		{
			Arrays.stream(task.getTargetNames())
				.map(MaxHitPlugin::targetNamePattern)
				.forEach(targetNames::add);

			targetNames.add(targetNamePattern(taskName.replaceAll("s$", "")));
		}
	}

	private static Pattern targetNamePattern(final String targetName)
	{
		return Pattern.compile("(?:\\s|^)" + targetName + "(?:\\s|$)", Pattern.CASE_INSENSITIVE);
	}

	@VisibleForTesting
	void setNoTask()
	{
		setTask("", 0, 0, null);
	}

	private void setTask(String name, int amt, int initAmt, String location)
	{
		taskName = name;
		amount = amt;
		initialAmount = initAmt;
		taskLocation = location;

		Task task = Task.getTask(name);
		rebuildTargetNames(task);
	}

	@Subscribe
	public void onItemContainerChanged(final ItemContainerChanged event)
	{
		//If equipment is changed, recalculate
		if (event.getItemContainer() != client.getItemContainer(InventoryID.WORN))
		{
			return;
		}

		equippedItems = event.getItemContainer();

		if (maxHitCalculator == null)
		{
			return;
		}

		maxHitCalculator.setEquippedItems(equippedItems);
		maxHitCalculator.calculateMaxHit();
		specialAttackCalculator.setEquippedItems(equippedItems);
		checkIsWieldingSpecialAttackWeapon();
	}

	// Update on stat change
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Called upon XP gain, level gained, or boosted level gained
		// Question is, should this be called every time i.e. every attack or just upon level up?
		if (maxHitCalculator == null)
		{
			return;
		}

		Skill[] skills = { Skill.STRENGTH, Skill.RANGED, Skill.MAGIC, Skill.HITPOINTS };

		for (Skill skill : skills)
		{
			if (event.getSkill() != skill)
			{
				continue;
			}

			maxHitCalculator.calculateMaxHit();
			return;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// COM_MODE = Attack Style
		// COMBAT_WEAPON_CATEGORY = Weapon Style
		int varpId = event.getVarpId();
		int varbitId = event.getVarbitId();

		if (varpId == VarPlayerID.COM_MODE
			|| varpId == VarPlayerID.COM_STANCE
			|| varbitId == VarbitID.COMBAT_WEAPON_CATEGORY
			|| varbitId == VarbitID.AUTOCAST_DEFMODE)
		{
			replaceCalculatorAndMaxHit();
		}
		else if (varbitId == VarbitID.PRAYER_ALLACTIVE)
		{
			// Only re-calculate for select prayers
			for (PrayerType prayer : PrayerType.values())
			{
				if (!prayer.isActive(client))
				{
					continue;
				}
				maxHitCalculator.calculateMaxHit();
				return;
			}
		}
		else if (varbitId == VarbitID.AUTOCAST_SPELL)
		{
			maxHitCalculator.calculateMaxHit();
		}
		else if (varpId == VarPlayerID.SLAYER_COUNT
				|| varpId == VarPlayerID.SLAYER_AREA
				|| varpId == VarPlayerID.SLAYER_TARGET
				|| varbitId == VarbitID.SLAYER_TARGET_BOSSID
				|| varpId == VarPlayerID.SLAYER_COUNT_ORIGINAL
				|| varbitId == VarbitID.SLAYER_MODIFIER_ID
				|| varbitId == VarbitID.SLAYER_MODIFIER_VALUE
				|| varbitId == VarbitID.SLAYER_MODIFIER_NEGATIVE)
		{
			clientThread.invokeLater(this::updateTask);
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		// Check if user has reset enabled
		if (!config.resetMaxHit())
		{
			return;
		}

		// If user has an opponent
		if (maxHitCalculator.opponent  == null)
		{
			return;
		}

		// And a previously saved time
		if (lastTime == null)
		{
			return;
		}

		// And user is no longer interacting
		if (client.getLocalPlayer().getInteracting() != null)
		{
			return;
		}

		// And the wait time has been exceeded
		if (Duration.between(lastTime, Instant.now()).compareTo(WAIT) > 0)
		{
			activeSpell = null;
			maxHitCalculator.opponent  = null;
			maxHitCalculator.calculateMaxHit();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied hitsplatApplied)
	{
		if (maxHitCalculator == null)
		{
			return;
		}
		Actor actor = hitsplatApplied.getActor();
		Hitsplat hitsplat = hitsplatApplied.getHitsplat();
		if (actor == null)
		{
			return;
		}
		if (!(actor instanceof NPC))
		{
			return;
		}
		if (hitsplat.isOthers())
		{
			return;
		}
		lastTime = Instant.now();
		maxHitCalculator.opponent = actor;
		maxHitCalculator.calculateMaxHit();
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		final Actor eventActor = event.getActor();

		if (eventActor == null)
			return;

		// Check that event target is who we're interacting with
		if (eventActor != client.getLocalPlayer())
			return;


		// Okay, we've found a match for our target
		// Now Iterate over standard spellbook spells looking to see if the projectile is a spell
		for (MagicSpell spell : MagicSpell.getStandardSpells())
		{
			// Looks for matching id
			if (!eventActor.hasSpotAnim(spell.getProjectileId()))
			{
				continue;
			}

			// Don't recalc if we're already using the same spell
			if (activeSpell == spell)
				return;


			activeSpell = spell;
			maxHitCalculator.calculateMaxHit();
		}
	}

	private void replaceCalculatorAndMaxHit()
	{
		AttackStyle attackStyle = StyleFactory.getAttackStyle(client);
		if (attackStyle == null || attackStyle == AttackStyle.OTHER)
		{
			return;
		}

		CombatStyle combatStyle = StyleFactory.getCombatType(attackStyle);
		maxHitCalculator = maxHitCalculatorFactory.create(combatStyle, attackStyle);
		maxHitCalculator.calculateMaxHit();
	}

	private void checkIsWieldingSpecialAttackWeapon()
	{
		if (equippedItems == null)
		{
			return;
		}
		Item weapon = equippedItems.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
		{
			isWieldingSpecialAttackWeapon = false;
			return;
		}
		isWieldingSpecialAttackWeapon = client.getEnum(WEAPON_SPECIAL_REQS).getIntValue(weapon.getId()) > 0;
	}
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.PrayerType;
import com.maxhit.Prayers;
import com.maxhit.equipment.EquipmentFunctions;
import com.maxhit.equipment.SalveAmulet;
import com.maxhit.monsters.UndeadMonsters;
import com.maxhit.sets.EliteVoidSet;
import com.maxhit.sets.VoidSet;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class BonusCalculator
{


	private final VoidSet voidSet;
	private final EliteVoidSet eliteVoidSet;
	private final Client client;
	private final Skill skill;

	public BonusCalculator(Client client, Skill skill)
	{
		this.client = client;
		this.skill = skill;
		voidSet = new VoidSet(client, skill);
		eliteVoidSet = new EliteVoidSet(client, skill);
	}

	public double getSalveBonus(ItemContainer equippedItems, Actor opponent)
	{
		// Check if opponent is undead
		NPC npc = (NPC) opponent;

		if (npc == null)
		{
			return 0.0;
		}

		if (!UndeadMonsters.ID_LIST.contains(npc.getId()))
		{
			return 0.0;
		}

		for (SalveAmulet amuletType : SalveAmulet.values())
		{
			if (amuletType.isEquipped(equippedItems))
			{
				return amuletType.getBonus(skill);
			}
		}
		return 0.0;
	}

	public double getVoidBonus()
	{
		if (voidSet.isWearingSet())
			return voidSet.getMultiplier();

		if (eliteVoidSet.isWearingSet())
			return eliteVoidSet.getMultiplier();
		return 1.0;
	}

	public double getPrayerBonus()
	{
		switch (skill)
		{
			case STRENGTH:
				for (Map.Entry<PrayerType, Double> entry : Prayers.STRENGTH_PRAYERS.entrySet())
				{
					if (entry.getKey().isActive(client))
					{
						return entry.getValue(); // Return the first active prayer found
					}
				}
				break;
			case RANGED:
				for (Map.Entry<PrayerType, Double> entry : Prayers.RANGED_PRAYERS.entrySet())
				{
					if (entry.getKey().isActive(client))
					{
						return entry.getValue(); // Return the first active prayer found
					}
				}
				break;
			case MAGIC:
				for (Map.Entry<PrayerType, Double> entry : Prayers.MAGIC_PRAYERS.entrySet())
				{
					if (entry.getKey().isActive(client))
					{
						return entry.getValue(); // Return the first active prayer found
					}
				}
				return 0.0;
		}
		return 1.0;
	}

	public double getSlayerBonus(MaxHitPlugin plugin, ItemContainer equippedItems, Actor opponent)
	{
		// Check if opponent is in slayer task
		NPC npc = (NPC) opponent;

		if (npc == null)
		{
			return 0.0;
		}

		if (!plugin.isTarget(npc))
		{
			return 0.0;
		}

		// Check head slot

		Item headSlot = equippedItems.getItem(EquipmentInventorySlot.HEAD.ordinal());

		if (headSlot == null)
		{
			return 0.0;
		}

		String headSlotName = EquipmentFunctions.GetEquippedItemString(client, equippedItems, EquipmentInventorySlot.HEAD).toLowerCase();

		// Check for black mask
		if (headSlotName.contains("black mask") ||  headSlotName.contains("slayer helmet"))
		{
			switch (skill)
			{
				case STRENGTH:
					return 0.1667;
				case RANGED:
				case MAGIC:
					if (headSlotName.contains("(i)"))
					{
						return 0.15;
					}
					else
					{
						return 0.0;
					}
			}
		}

		return 0.0;
	}
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.NextMaxHitReqs;
import com.maxhit.monsters.MonsterFlatArmour;
import com.maxhit.sets.EquipmentSet;
import com.maxhit.styles.AttackStyle;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

public abstract class MaxHitCalculator
{
	protected final MaxHitPlugin plugin;
    protected final Client client;
    protected final ItemManager itemManager;
	protected ItemContainer equippedItems;
	@Getter
    protected Skill skill;
	@Setter
	protected AttackStyle attackStyle;
	protected BonusCalculator bonusCalculator;
    protected double effectiveStrength;
    protected double strengthBonus;
    protected double prayerBonus;
    protected double styleBonus;
	protected double salveBonus;
	protected double slayerBonus;
    protected double voidBonus;
	protected double flatArmour;

	@Nullable
    public Actor opponent;
	@Getter
    protected double maxHit;
	@Getter
	protected NextMaxHitReqs nextMaxHitReqs;

	@Inject
    protected MaxHitCalculator (MaxHitPlugin plugin, Client client, ItemManager itemManager, Skill skill, AttackStyle attackStyle)
    {
		this.plugin = plugin;
		this.client = client;
		this.itemManager = itemManager;
        this.skill = skill;
		this.attackStyle = attackStyle;
		this.equippedItems = client.getItemContainer(InventoryID.WORN);
		EquipmentSet.setEquippedItems(equippedItems);
		bonusCalculator = new BonusCalculator(client, skill);
        maxHit = 0.0;
        voidBonus = 1.0;
		salveBonus = 0.0;
		flatArmour = 0.0;
    }

	public void setEquippedItems(ItemContainer equippedItems)
	{
		this.equippedItems = equippedItems;
		EquipmentSet.setEquippedItems(equippedItems);
	}

	protected void reset()
	{
		styleBonus = 0.0;
		voidBonus = 1.0;
		prayerBonus = 1.0;
		flatArmour = 0.0;
	}

	protected abstract void getStyleBonus();

	protected void getVoidBonus()
	{
		voidBonus = bonusCalculator.getVoidBonus();
		if (skill == Skill.MAGIC)
			voidBonus -= 1.0;
	}

	protected void getPrayerBonus()
	{
		prayerBonus = bonusCalculator.getPrayerBonus();
	}

	protected void getEffectiveStrength()
	{
		getStyleBonus();
		getPrayerBonus();
		getVoidBonus();
		// getValue() gets boosted value
		effectiveStrength = Math.floor(Math.floor((getSkillLevel() * prayerBonus) + styleBonus + 8) * voidBonus);
	}

    protected void getStrengthBonus()
	{
		strengthBonus = StrengthBonusCalculator.getStrengthBonus(equippedItems, itemManager, skill);
	}

	protected void getFlatArmour()
	{
		flatArmour = 0.0;

		if (opponent == null)
		{
			return;
		}

		NPC npc = (NPC) opponent;
		String npcName = npc.getName();

		if (npcName == null)
		{
			return;
		}
		for (MonsterFlatArmour monster : MonsterFlatArmour.values())
		{
			if (monster.getId() != npc.getId())
			{
				continue;
			}

			flatArmour = monster.getFlatArmour();
			return;
		}
	}

    public abstract void calculateMaxHit();

	protected int getSkillLevel()
	{
		return client.getBoostedSkillLevel(this.skill);
	}

	protected void getSalveBonus()
	{
		salveBonus = bonusCalculator.getSalveBonus(equippedItems, opponent);
	}

	protected void getSlayerBonus() {slayerBonus = bonusCalculator.getSlayerBonus(this.plugin, equippedItems, opponent);}

	protected abstract void calculateNextMaxHitRequirements();
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.styles.AttackStyle;
